package com.sathavahana.kalamkari.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="carts") public class Cart { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @OneToMany(mappedBy="cart",cascade=CascadeType.ALL,orphanRemoval=true) private List<CartItem> items=new ArrayList<>(); @Column(name="updated_at") private Instant updatedAt=Instant.now(); public Cart(){} public Cart(User u){user=u;} public Long getId(){return id;} public User getUser(){return user;} public List<CartItem> getItems(){return items;} public void touch(){updatedAt=Instant.now();}}
